"""Seating rows for a class, sorted by last name."""


def _split_names(students, size):
    names = sorted(stud.display_name for stud in students)
    return [
        names[spot:spot + size]
        for spot in range(0, len(names), size)
    ]

# ---
def seating_rows(students, per_row):
    if per_row < 1 or not students:
        raise ValueError("need students and seats")
    rows = _split_names(students, per_row)
    return [
        f"Row {numb}: " + " | ".join(names)
        for numb, names in enumerate(rows, 1)
    ]

