# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def _pupil(last, first):
    return Student("1", last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            _pupil("Halloway", "Juno"),
            _pupil("Dunmere", "Piet"),
            _pupil("Quillon", "Ada")
        ]

    def test_sorted_rows(self):
        self.assertEqual(
            seating_rows(self.pupils, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quillon, Ada"
            ]
        )

    def test_bad_seat_count(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows(self.pupils, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
